use tiny_http::{Server,Response};
fn u(n:i64)->&'static str{["cero","uno","dos","tres","cuatro","cinco","seis","siete","ocho","nueve"][n as usize]}
fn c(n:i64)->String{let esp=std::collections::HashMap::from([(10,"diez"),(11,"once"),(12,"doce"),(13,"trece"),(14,"catorce"),(15,"quince"),(16,"dieciseis"),(17,"diecisiete"),(18,"dieciocho"),(19,"diecinueve"),(20,"veinte"),(21,"veintiuno"),(22,"veintidos"),(23,"veintitres"),(24,"veinticuatro"),(25,"veinticinco"),(26,"veintiseis"),(27,"veintisiete"),(28,"veintiocho"),(29,"veintinueve")]);let dec=std::collections::HashMap::from([(30,"treinta"),(40,"cuarenta"),(50,"cincuenta"),(60,"sesenta"),(70,"setenta"),(80,"ochenta"),(90,"noventa")]);let cie=std::collections::HashMap::from([(100,"cien"),(200,"doscientos"),(300,"trescientos"),(400,"cuatrocientos"),(500,"quinientos"),(600,"seiscientos"),(700,"setecientos"),(800,"ochocientos"),(900,"novecientos")]);if n<10{return u(n).to_string()}if let Some(v)=esp.get(&n){return v.to_string()}if n<100{let d=n/10*10;let un=n%10;return if un>0{format!("{} y {}",dec[&d],u(un))}else{dec[&d].to_string()}}if let Some(v)=cie.get(&n){return v.to_string()}let ce=n/100*100;let r=n%100;format!("{} {}",if ce==100{"ciento"}else{cie[&ce]},c(r))}
fn num(n:i64)->String{if n==0{return "cero".to_string()}if n<0{return format!("menos {}",num(-n))}if n<1000{return c(n)}if n<1_000_000{let m=n/1000;let r=n%1000;let p=if m==1{"mil".to_string()}else{format!("{} mil",num(m))};return if r>0{format!("{} {}",p,c(r))}else{p}}let m=n/1_000_000;let r=n%1_000_000;let p=if m==1{"un millon".to_string()}else{format!("{} millones",num(m))};if r>0{format!("{} {}",p,num(r))}else{p}}
fn main(){let server=Server::http("0.0.0.0:3000").unwrap();println!("Servidor en http://localhost:3000/?n=10");for rq in server.incoming_requests(){let url=rq.url().to_string();let n=url.split("n=").nth(1).unwrap_or("10").parse::<i64>().unwrap_or(10);let _=rq.respond(Response::from_string(num(n)));}}
